import React, { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ReferenceLine, ResponsiveContainer } from 'recharts';
import { Calendar, TrendingDown, Target, Scale, Download, Upload, Cloud } from 'lucide-react';
import { initializeApp } from 'firebase/app';
import { getFirestore, doc, setDoc, onSnapshot } from 'firebase/firestore';

// 🔥 YOUR FIREBASE CONFIG
const firebaseConfig = {
  apiKey: "AIzaSyBSN-2_eniZFGBMzqn9cRiThiMSe2BzjiA",
  authDomain: "jackson-weight-tracker.firebaseapp.com",
  projectId: "jackson-weight-tracker",
  storageBucket: "jackson-weight-tracker.firebasestorage.app",
  messagingSenderId: "671853635877",
  appId: "1:671853635877:web:899f5bf9694bae2ea712cc"
};

const app = initializeApp(firebaseConfig);
const db = getFirestore(app);

const WeightLossTracker = () => {
  const startDate = new Date('2025-10-05');
  const endDate = new Date('2025-12-31');
  const startWeight = 193;
  const goalWeight = 163;
  
  const generateProjectedData = () => {
    const data = [];
    const totalDays = Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24));
    
    const fastingPeriods = [
      { start: new Date('2025-10-05'), end: new Date('2025-10-10'), loss: 5 },
      { start: new Date('2025-11-05'), end: new Date('2025-11-10'), loss: 4.5 },
      { start: new Date('2025-12-10'), end: new Date('2025-12-15'), loss: 4.5 }
    ];
    
    let currentWeight = startWeight;
    const weeklyOMADLoss = 1.5;
    
    for (let i = 0; i <= totalDays; i++) {
      const currentDate = new Date(startDate);
      currentDate.setDate(startDate.getDate() + i);
      
      const inFast = fastingPeriods.find(period => 
        currentDate >= period.start && currentDate <= period.end
      );
      
      if (inFast) {
        const fastDays = Math.ceil((inFast.end - inFast.start) / (1000 * 60 * 60 * 24));
        const dailyFastLoss = inFast.loss / fastDays;
        currentWeight -= dailyFastLoss;
      } else {
        currentWeight -= weeklyOMADLoss / 7;
      }
      
      data.push({
        date: currentDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
        fullDate: currentDate.toISOString().split('T')[0],
        projected: Math.round(currentWeight * 10) / 10,
        goal: goalWeight
      });
    }
    
    return data;
  };

  const [projectedData] = useState(generateProjectedData());
  const [actualWeights, setActualWeights] = useState([{ date: '2025-10-05', weight: 193 }]);
  const [newWeight, setNewWeight] = useState('');
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [syncStatus, setSyncStatus] = useState('⚡ Connecting...');

  useEffect(() => {
    const docRef = doc(db, 'weightData', 'user-tracker');
    
    const unsubscribe = onSnapshot(docRef, (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.weights) {
          setActualWeights(data.weights);
          setSyncStatus('☁️ Synced');
        }
      } else {
        const defaultData = [{ date: '2025-10-05', weight: 193 }];
        setDoc(docRef, { weights: defaultData });
        setSyncStatus('☁️ Synced');
      }
    }, (error) => {
      console.error('Firebase error:', error);
      setSyncStatus('❌ Offline');
      const saved = localStorage.getItem('weightTrackerData');
      if (saved) {
        try {
          setActualWeights(JSON.parse(saved));
        } catch (e) {
          console.error('Error:', e);
        }
      }
    });

    return () => unsubscribe();
  }, []);

  const saveToFirebase = async (weights) => {
    setSyncStatus('💾 Saving...');
    try {
      const docRef = doc(db, 'weightData', 'user-tracker');
      await setDoc(docRef, { weights });
      setSyncStatus('☁️ Synced');
      localStorage.setItem('weightTrackerData', JSON.stringify(weights));
    } catch (error) {
      console.error('Save error:', error);
      setSyncStatus('❌ Save failed');
      localStorage.setItem('weightTrackerData', JSON.stringify(weights));
    }
  };

  const addWeight = () => {
    if (newWeight && selectedDate) {
      const weight = parseFloat(newWeight);
      if (weight > 0) {
        const newEntry = { date: selectedDate, weight };
        const updated = [...actualWeights, newEntry].sort((a, b) => 
          new Date(a.date) - new Date(b.date)
        );
        setActualWeights(updated);
        saveToFirebase(updated);
        setNewWeight('');
      }
    }
  };

  const exportData = () => {
    const dataStr = JSON.stringify(actualWeights, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'weight-tracker-data.json';
    link.click();
  };

  const importData = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const imported = JSON.parse(e.target.result);
          setActualWeights(imported);
          saveToFirebase(imported);
          alert('Data imported successfully!');
        } catch (error) {
          alert('Error importing data.');
        }
      };
      reader.readAsText(file);
    }
  };

  const chartData = projectedData.map(proj => {
    const actual = actualWeights.find(a => a.date === proj.fullDate);
    return { ...proj, actual: actual ? actual.weight : null };
  });

  const currentActualWeight = actualWeights[actualWeights.length - 1]?.weight || startWeight;
  const weightLost = startWeight - currentActualWeight;
  const weightToGo = currentActualWeight - goalWeight;
  const progressPercent = ((startWeight - currentActualWeight) / (startWeight - goalWeight) * 100).toFixed(1);

  const milestones = [
    { weight: 185, label: 'First 8 lbs', achievement: '~Week 3' },
    { weight: 175, label: 'Belly noticeably smaller', achievement: '~Week 6' },
    { weight: 170, label: 'Down 2 pant sizes', achievement: '~Week 9' },
    { weight: 163, label: 'Goal: Much flatter belly', achievement: 'Dec 31' }
  ];

  return (
    <div className="p-3 sm:p-6 max-w-6xl mx-auto bg-gradient-to-br from-blue-50 to-indigo-50 min-h-screen">
      <div className="bg-white rounded-lg shadow-lg p-4 sm:p-6 mb-4 sm:mb-6">
        <div className="flex flex-col sm:flex-row justify-between items-start gap-3">
          <div className="w-full sm:w-auto">
            <h1 className="text-2xl sm:text-3xl font-bold text-gray-800 mb-2 flex items-center gap-2">
              <TrendingDown className="text-blue-600" size={24} />
              Weight Loss Tracker
            </h1>
            <p className="text-sm sm:text-base text-gray-600">Oct 5 - Dec 31, 2025</p>
            <p className="text-xs sm:text-sm text-gray-500 flex items-center gap-1 mt-1">
              <Cloud size={14} /> {syncStatus}
            </p>
          </div>
          <div className="flex gap-2 w-full sm:w-auto">
            <button onClick={exportData} className="flex-1 sm:flex-initial flex items-center justify-center gap-2 px-3 sm:px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors text-sm">
              <Download size={16} />
              <span className="hidden sm:inline">Export</span>
            </button>
            <label className="flex-1 sm:flex-initial flex items-center justify-center gap-2 px-3 sm:px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors cursor-pointer text-sm">
              <Upload size={16} />
              <span className="hidden sm:inline">Import</span>
              <input type="file" accept=".json" onChange={importData} className="hidden" />
            </label>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4 mb-4 sm:mb-6">
        <div className="bg-white rounded-lg shadow p-3 sm:p-4">
          <div className="flex flex-col sm:flex-row items-start sm:items-center sm:justify-between gap-2">
            <div className="w-full">
              <p className="text-gray-500 text-xs sm:text-sm">Current Weight</p>
              <p className="text-xl sm:text-2xl font-bold text-gray-800">{currentActualWeight} lbs</p>
            </div>
            <Scale className="text-blue-500 hidden sm:block" size={32} />
          </div>
        </div>
        
        <div className="bg-white rounded-lg shadow p-3 sm:p-4">
          <div className="flex flex-col sm:flex-row items-start sm:items-center sm:justify-between gap-2">
            <div className="w-full">
              <p className="text-gray-500 text-xs sm:text-sm">Lost So Far</p>
              <p className="text-xl sm:text-2xl font-bold text-green-600">-{weightLost.toFixed(1)} lbs</p>
            </div>
            <TrendingDown className="text-green-500 hidden sm:block" size={32} />
          </div>
        </div>
        
        <div className="bg-white rounded-lg shadow p-3 sm:p-4">
          <div className="flex flex-col sm:flex-row items-start sm:items-center sm:justify-between gap-2">
            <div className="w-full">
              <p className="text-gray-500 text-xs sm:text-sm">To Goal</p>
              <p className="text-xl sm:text-2xl font-bold text-orange-600">{weightToGo.toFixed(1)} lbs</p>
            </div>
            <Target className="text-orange-500 hidden sm:block" size={32} />
          </div>
        </div>
        
        <div className="bg-white rounded-lg shadow p-3 sm:p-4">
          <div className="flex flex-col sm:flex-row items-start sm:items-center sm:justify-between gap-2">
            <div className="w-full">
              <p className="text-gray-500 text-xs sm:text-sm">Progress</p>
              <p className="text-xl sm:text-2xl font-bold text-purple-600">{progressPercent}%</p>
            </div>
            <div className="text-purple-500 text-2xl sm:text-3xl font-bold hidden sm:block">📊</div>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-lg p-4 sm:p-6 mb-4 sm:mb-6">
        <h2 className="text-lg sm:text-xl font-bold text-gray-800 mb-4">Weight Loss Progress</h2>
        <div className="w-full h-64 sm:h-96">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chartData} margin={{ top: 5, right: 10, left: -20, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" tick={{ fontSize: 10 }} interval="preserveStartEnd" angle={-45} textAnchor="end" height={60} />
              <YAxis domain={[155, 195]} tick={{ fontSize: 10 }} />
              <Tooltip />
              <Legend wrapperStyle={{ fontSize: '12px' }} />
              <ReferenceLine y={goalWeight} stroke="#10b981" strokeDasharray="3 3" label={{ value: "Goal", fontSize: 10 }} />
              <Line type="monotone" dataKey="projected" stroke="#3b82f6" strokeWidth={2} name="Projected" dot={false} />
              <Line type="monotone" dataKey="actual" stroke="#10b981" strokeWidth={3} name="Actual" dot={{ fill: '#10b981', r: 4 }} connectNulls={false} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-lg p-4 sm:p-6 mb-4 sm:mb-6">
        <h2 className="text-lg sm:text-xl font-bold text-gray-800 mb-4 flex items-center gap-2">
          <Calendar className="text-blue-600" size={20} />
          Log Your Weight
        </h2>
        <div className="flex flex-col sm:flex-row gap-3 sm:gap-4">
          <div className="flex-1">
            <label className="block text-sm font-medium text-gray-700 mb-2">Date</label>
            <input type="date" value={selectedDate} onChange={(e) => setSelectedDate(e.target.value)} className="w-full px-4 py-3 sm:py-2 text-base border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" min="2025-10-05" max="2025-12-31" />
          </div>
          <div className="flex-1">
            <label className="block text-sm font-medium text-gray-700 mb-2">Weight (lbs)</label>
            <input type="number" step="0.1" value={newWeight} onChange={(e) => setNewWeight(e.target.value)} placeholder="Enter weight" className="w-full px-4 py-3 sm:py-2 text-base border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
          </div>
          <div className="sm:flex-initial sm:self-end">
            <button onClick={addWeight} className="w-full sm:w-auto px-6 py-3 sm:py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium text-base">
              Add Entry
            </button>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-lg p-4 sm:p-6 mb-4 sm:mb-6">
        <h2 className="text-lg sm:text-xl font-bold text-gray-800 mb-4">Milestones</h2>
        <div className="space-y-3">
          {milestones.map((milestone, idx) => {
            const achieved = currentActualWeight <= milestone.weight;
            return (
              <div key={idx} className={`p-3 sm:p-4 rounded-lg border-2 ${achieved ? 'border-green-500 bg-green-50' : 'border-gray-200 bg-gray-50'}`}>
                <div className="flex items-center justify-between gap-3">
                  <div className="flex items-center gap-2 sm:gap-3 flex-1">
                    <div className={`w-8 h-8 sm:w-10 sm:h-10 rounded-full flex items-center justify-center text-sm sm:text-base ${achieved ? 'bg-green-500 text-white' : 'bg-gray-300 text-gray-600'}`}>
                      {achieved ? '✓' : idx + 1}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm sm:text-base font-semibold text-gray-800 truncate">{milestone.weight} lbs - {milestone.label}</p>
                      <p className="text-xs sm:text-sm text-gray-600">{milestone.achievement}</p>
                    </div>
                  </div>
                  {achieved && <span className="text-green-600 font-bold text-sm hidden sm:inline">ACHIEVED! 🎉</span>}
                  {achieved && <span className="text-green-600 text-xl sm:hidden">🎉</span>}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-lg p-4 sm:p-6 mb-4 sm:mb-6">
        <h2 className="text-lg sm:text-xl font-bold text-gray-800 mb-4">Fasting Schedule</h2>
        <div className="space-y-3">
          <div className="p-3 sm:p-4 bg-blue-50 border-l-4 border-blue-500 rounded">
            <p className="text-sm sm:text-base font-semibold text-blue-900">Oct 5-10: 5-Day Fast</p>
            <p className="text-xs sm:text-sm text-blue-700">Expected loss: ~5 lbs | Target: 188 lbs</p>
          </div>
          <div className="p-3 sm:p-4 bg-purple-50 border-l-4 border-purple-500 rounded">
            <p className="text-sm sm:text-base font-semibold text-purple-900">Nov 5-10: 5-Day Fast</p>
            <p className="text-xs sm:text-sm text-purple-700">Expected loss: ~4.5 lbs | Target: 175 lbs</p>
          </div>
          <div className="p-3 sm:p-4 bg-indigo-50 border-l-4 border-indigo-500 rounded">
            <p className="text-sm sm:text-base font-semibold text-indigo-900">Dec 10-15: 5-Day Fast</p>
            <p className="text-xs sm:text-sm text-indigo-700">Expected loss: ~4.5 lbs | Target: 163 lbs</p>
          </div>
          <div className="p-3 sm:p-4 bg-gray-50 border-l-4 border-gray-400 rounded">
            <p className="text-sm sm:text-base font-semibold text-gray-800">Between: OMAD</p>
            <p className="text-xs sm:text-sm text-gray-600">~1.5 lbs/week | 1,500-1,800 cal | Low-carb</p>
          </div>
        </div>
      </div>

      {actualWeights.length > 1 && (
        <div className="bg-white rounded-lg shadow-lg p-4 sm:p-6">
          <h2 className="text-lg sm:text-xl font-bold text-gray-800 mb-4">Weight Log</h2>
          <div className="overflow-x-auto -mx-4 sm:mx-0">
            <table className="w-full min-w-full">
              <thead>
                <tr className="border-b-2 border-gray-200">
                  <th className="text-left py-2 px-2 sm:px-4 text-xs sm:text-sm">Date</th>
                  <th className="text-left py-2 px-2 sm:px-4 text-xs sm:text-sm">Weight</th>
                  <th className="text-left py-2 px-2 sm:px-4 text-xs sm:text-sm">Change</th>
                  <th className="text-left py-2 px-2 sm:px-4 text-xs sm:text-sm">Total</th>
                </tr>
              </thead>
              <tbody>
                {actualWeights.map((entry, idx) => {
                  const change = idx > 0 ? (entry.weight - actualWeights[idx - 1].weight).toFixed(1) : 0;
                  const totalLost = (startWeight - entry.weight).toFixed(1);
                  return (
                    <tr key={idx} className="border-b border-gray-100">
                      <td className="py-2 px-2 sm:px-4 text-xs sm:text-sm">{new Date(entry.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</td>
                      <td className="py-2 px-2 sm:px-4 text-xs sm:text-sm font-semibold">{entry.weight}</td>
                      <td className={`py-2 px-2 sm:px-4 text-xs sm:text-sm ${change < 0 ? 'text-green-600' : 'text-red-600'}`}>
                        {change !== 0 && (change > 0 ? '+' : '')}{change}
                      </td>
                      <td className="py-2 px-2 sm:px-4 text-xs sm:text-sm text-green-600 font-semibold">-{totalLost}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default WeightLossTracker;